pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != caller2);

        uint256 initialContractBalance = address(c).balance;
        uint256 initialBalance1 = c.balances(caller1);
        uint256 initialBalance2 = c.balances(caller2);

        // Simulate two deposits
        vm.deal(caller1, amount1);
        vm.prank(caller1);
        (bool success1, ) = address(c).call{value: amount1}("");

        vm.deal(caller2, amount2);
        vm.prank(caller2);
        (bool success2, ) = address(c).call{value: amount2}("");

        // Both deposits succeed
        vm.assume(success1 && success2);

        // Caller1 withdraws
        vm.prank(caller1);
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        vm.assume(withdrawSuccess);

        // Invariant: total Ether in contract + sum of balances = initial + deposits
        uint256 sumBalances = c.balances(caller1) + c.balances(caller2);
        uint256 totalNow = address(c).balance + sumBalances;
        uint256 expected = initialContractBalance + initialBalance1 + initialBalance2 + amount1 + amount2;

        assertTrue(totalNow == expected, "Invariant broken: total Ether + balances mismatch");
    }
}

