pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // Give some initial ETH to the contract (e.g., via another address)
        vm.deal(address(c), 1 ether);
        // Also give some ETH to the caller to simulate a fallback deposit
        vm.deal(caller, 1 ether);

        // Caller deposits some ETH via fallback
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0.5 ether}("");
        require(success);

        // Record contract balance before withdrawal
        uint256 balanceBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(caller);

        // Caller withdraws
        vm.prank(caller);
        c.withdraw();

        // Rule: after withdrawal, contract balance decreased by exactly the caller's previous balance
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - callerBalanceBefore, "Balance decrease mismatch");
    }
}

